import { budget } from "../budget.grammar.js";

const SHARES = [0.5, 0.3, 0.2];

export default ($) => {
  let b = budget("split")
    .param("pay", { value: 3000, min: 0, max: 10000 })
    .start(2026, 1)
    .horizon(6);
  for (let i = 0; i < 3; i++) {
    b = b.account(`pot${i}`, { opening: 0 })
      .inflow("pay", (m) => $.pay * SHARES[i])
      .outflow("tax", (m) => (m.index % 3 === 0 ? Math.round($.pay * 0.1) : 0));
  }
  return b;
};

